package market

import (
	elasticSearch "github.com/olivere/elastic/v7"

)

func MarketBoolQuery(param map[string]string) *elasticSearch.BoolQuery {
	//BoolQuery 생성
	query := elasticSearch.NewBoolQuery()

	//bool Query 배열
	var mustMatchQueryList []elasticSearch.Query
	var filterTermQueryList []elasticSearch.Query

	searchQuery, mustNotMatchQueryList := KeywordQuery(param)

	if len(param["saleType"]) > 0 && param["saleType"] != "P" {
		if param["saleType"] == "O" {
			saleTypeMatchQuery := elasticSearch.NewMatchQuery("saleType", "N")
			mustNotMatchQueryList = append(mustNotMatchQueryList, saleTypeMatchQuery)
		} else {
			saleTypeTermQuery := elasticSearch.NewTermQuery("saleType", param["saleType"])
			filterTermQueryList = append(filterTermQueryList, saleTypeTermQuery)
		}
	}

	if searchQuery != nil {
		filterTermQueryList = append(filterTermQueryList, searchQuery)
	}

	if len(mustMatchQueryList) > 0 {
		query.Must(mustMatchQueryList...)
	}
	if len(mustNotMatchQueryList) > 0 {
		query.MustNot(mustNotMatchQueryList...)
	}
	if len(EsProductFt(param)) > 0 {
		for _, value := range EsProductFt(param) {
			filterTermQueryList = append(filterTermQueryList, value)
		}
	}
	if len(filterTermQueryList) > 0 {
		query.Filter(filterTermQueryList...)
	}

	return query
}

