	elasticSearch "github.com/olivere/elastic/v7"
)

func EsProductFt(data map[string]string) []elasticSearch.Query {
	var filterTermQueryList []elasticSearch.Query

	if len(data["newProd"]) > 0 {
		newProdTermQuery := elasticSearch.NewTermQuery("newProd", data["newProd"])
		filterTermQueryList = append(filterTermQueryList, newProdTermQuery)
	}

	if len(data["buyWay"]) > 0 {
		buyWayTermQuery := elasticSearch.NewTermQuery("buyWay", data["buyWay"])
		filterTermQueryList = append(filterTermQueryList, buyWayTermQuery)
	}

	if len(data["locale"]) > 0 {
		localeTermQuery := elasticSearch.NewTermQuery("localeCode1", data["locale"])
		filterTermQueryList = append(filterTermQueryList, localeTermQuery)
	}

	if len(data["userLevel"]) > 0 {
		userLevels := strings.Split(data["userLevel"], "|")
		userLevelTermQuery := elasticSearch.NewTermsQueryFromStrings("userLevel", userLevels...)
		filterTermQueryList = append(filterTermQueryList, userLevelTermQuery)
	}

	if cate1, err := strconv.Atoi(data["cate1"]); err == nil && cate1 > 0 {
		cate1TermQuery := elasticSearch.NewTermQuery("categoryCode1", data["cate1"])
		filterTermQueryList = append(filterTermQueryList, cate1TermQuery)
	}

	if cate2, err := strconv.Atoi(data["cate2"]); err == nil && cate2 > 0 {
		cate2TermQuery := elasticSearch.NewTermQuery("categoryCode2", data["cate2"])
		filterTermQueryList = append(filterTermQueryList, cate2TermQuery)
	}

	if cate3, err := strconv.Atoi(data["cate3"]); err == nil && cate3 > 0 {
		cate3TermQuery := elasticSearch.NewTermQuery("categoryCode3", data["cate3"])
		filterTermQueryList = append(filterTermQueryList, cate3TermQuery)
	}

	if cate4, err := strconv.Atoi(data["cate4"]); err == nil && cate4 > 0 {
		cate4TermQuery := elasticSearch.NewTermQuery("categoryCode4", data["cate4"])
		filterTermQueryList = append(filterTermQueryList, cate4TermQuery)
	}

	if len(data["status"]) > 0 {
		prodStatusTermQuery := elasticSearch.NewTermQuery("prod_status", data["status"])
		filterTermQueryList = append(filterTermQueryList, prodStatusTermQuery)
	}

	if len(data["group"]) > 0 {
		groupTermQuery := elasticSearch.NewTermQuery("group", data["group"])
		filterTermQueryList = append(filterTermQueryList, groupTermQuery)
	}

	if len(data["miniShop"]) > 0 {
		miniShopTermQuery := elasticSearch.NewTermQuery("bMiniShop", data["miniShop"])
		filterTermQueryList = append(filterTermQueryList, miniShopTermQuery)	
	}

	if len(data["display"]) > 0 {
		displayTermQuery := elasticSearch.NewTermQuery("bDisplay", data["display"])
		filterTermQueryList = append(filterTermQueryList, displayTermQuery)	
	}

	if len(data["minPrice"]) > 0 || len(data["maxPrice"]) > 0 {
		priceRangeQuery := elasticSearch.NewRangeQuery("price")
		// minPrice
		if minPrice, err := strconv.Atoi(data["minPrice"]); err == nil && minPrice > 0 {
			priceRangeQuery = priceRangeQuery.Gte(minPrice)
		}
		// maxPrice
		if maxPrice, err := strconv.Atoi(data["maxPrice"]); err == nil && maxPrice > 0 {
			priceRangeQuery = priceRangeQuery.Lte(maxPrice)
		}

		filterTermQueryList = append(filterTermQueryList, priceRangeQuery)
	}
	return filterTermQueryList
}

