package market

func EsProductRa(sort []string) (raString []string) {
	inputDate := sort[0]
	price := sort[1]

	if inputDate == "1" { // 날짜
		if price == "1" {
			raString = append(raString, "tInputDate")
			raString = append(raString, "ASC")
		} else {
			raString = append(raString, "tInputDate")
			raString = append(raString, "DESC")
		}
	} else if inputDate == "2" { // 가격
		if price == "1" {
			raString = append(raString, "price")
			raString = append(raString, "ASC")
		} else {
			raString = append(raString, "price")
			raString = append(raString, "DESC")
		}
	} else { // default
		raString = append(raString, "tInputDate")
		raString = append(raString, "ASC")
	}

	return
}

